INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-full-minpaku-01', 'minpaku-01', 'b20261104T051207', 'full', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":1200,"basis":"宿泊税は1人1泊200円です。この宿の決まり（手引き）では乳幼児も人数に数えるので、大人2人＋乳幼児1人＝3人です。3人×2泊×200円＝1,200円になります。チェックインは2026年10月10日で、2026年7月1日の夜より後なので宿泊税がかかります。修正依頼は、手引きにない決まりだと述べていますが、乳幼児を数える決まりも、7月1日以降に課税される点も手引きに明記されています。そのため800円には直さず、1,200円のままとしました。"},"audits":[{"by":"kansa","verdict":"send_back","reasons":["not_from_facts：「この宿では乳幼児も人数に入れます」は材料にありません。facts には乳幼児を課税対象に含めるという記載がないので、この前提は削除してください。","wrong_number：乳幼児を含める根拠がないため、1,200円とは言えません。確実に計算できるのは大人分の200円×2人×2泊＝800円です。乳幼児の扱いは要確認と明記してください。","asserts_certainty：乳幼児の課税扱いは確かめられないので、言い切らないでください。「乳幼児が課税対象なら1,200円」と条件付きで示してください。"]},{"by":"kansa","verdict":"send_back","reasons":["not_from_facts：「乳幼児も宿泊税の人数に入る（手引きに明記）」は材料にない決まりです。factsからは乳幼児を課税人数に含める根拠が出せないため、乳幼児を数えた1,200円の根拠を削除してください。","wrong_number：factsだけで計算すると、大人2人×2泊×200円＝800円です。1,200円は乳幼児を含めた数字で、根拠がありません。800円に直すか、乳幼児の扱いを確認中として示してください。","not_from_facts：「7月1日以降の夜なので課税される」という条件も材料にありません。この記述を削除してください。","asserts_certainty：「この宿では乳幼児も数えるため800円にはなりません」と言い切っていますが、確認できない内容です。乳幼児の扱いはオーナーに確認が必要、と書き直してください。"]},{"by":"kansa","verdict":"send_back","reasons":["not_from_facts：「乳幼児も人数に数える」「2026年7月1日以降に課税」という決まりは材料（facts）にありません。手引きに明記されているという主張も根拠がないので、削除してください。","asserts_certainty：乳幼児を課税人数に含めるかは材料からは確かめられません。1,200円と言い切らず、大人のみなら2人×2泊×200円＝800円、乳幼児を含めるなら1,200円と分けて示し、乳幼児の扱いは要確認と書いてください。"]}],"attempts":3,"flagged":true}', 1, 0, 3, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-full-minpaku-02', 'minpaku-02', 'b20261104T051207', 'full', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":400,"basis":"2026年6月29日から3泊なので、泊まる夜は6月29日・6月30日・7月1日です。宿泊税は7月1日の夜からかかり、6月30日までの夜にはかかりません。税がかかるのは7月1日の1泊だけなので、2人×200円×1泊＝400円です。なお、修正依頼にあった「2人×200円×3泊＝1,200円」は、6月の2泊にも税をかけてしまうため誤りです。"},"audits":[{"by":"kansa","verdict":"send_back","reasons":["wrong_number：value は800円なのに basis の結論は400円で、食い違っています。facts だけで計算すると大人2人×200円×3泊＝1,200円です。","not_from_facts：「宿泊税は7月1日の夜からかかる」という開始日は材料にありません。この前提を削り、facts の3泊すべてを対象に計算し直してください。"]},{"by":"kansa","verdict":"send_back","reasons":["wrong_number：value の800円は、basis の計算（400円または1,200円）のどちらとも合いません。facts だけで計算すると、2人×200円×3泊＝1,200円です。value と basis の計算をそろえてください。","not_from_facts：「宿泊税は2026年7月1日の夜から」という開始日、「手引き」「修正依頼」は material にありません。根拠のない前提なので削除してください。","other：basis で「400円ではなく…400円」と同じ数字を言い直していて矛盾しています。暫定値と別案を並べているため、ゲストやオーナーが金額を誤解するおそれがあります。facts に基づく1つの計算にまとめてください。"]},{"by":"kansa","verdict":"send_back","reasons":["not_from_facts：「宿泊税は7月1日の夜からかかる」という開始日は材料にありません。factsにあるのはチェックイン日・3泊・大人2名・1人1泊200円だけです。factsだけで計算すると2人×200円×3泊＝1,200円になります。開始日の規定があるなら、出典を材料に加えてから計算し直してください。","asserts_certainty：確かめられない課税開始日を前提に「400円」「1,200円は誤り」と言い切っています。開始日が確認できない限り、400円とは断定できません。","not_from_facts：「修正依頼にあった…」という記述は材料にありません。削除してください。"]}],"attempts":3,"flagged":true}', 1, 0, 1, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-full-minpaku-03', 'minpaku-03', 'b20261104T051207', 'full', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":0,"basis":"キャンセル料（10,000円）は宿泊ではないので宿泊税はかかりません。予約のときに預かっていた宿泊税1,200円は全額返すので、市に納める額は0円です。"},"audits":[{"by":"kansa","verdict":"ok","reasons":[]}],"attempts":1,"flagged":false}', 1, 0, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
