INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-no_audit-minpaku-01', 'minpaku-01', 'b20261104T051207', 'no_audit', 'claude-sonnet-5-5', '{"answer":{"value":1200,"basis":"宿泊税は1人1泊200円で、この宿では乳幼児も人数に入れます。大人2人＋乳幼児1人＝3人、泊数は2泊（2026年10月10日からで7月1日以降なので課税対象）。200円×3人×2泊＝1,200円です。"},"audits":[],"attempts":1,"flagged":false}', 1, 0, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
