INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-no_skill-minpaku-01', 'minpaku-01', 'b20261104T051207', 'no_skill', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":800,"basis":"宿泊税は1人1泊あたり200円です。課税対象は大人2人、宿泊は2泊なので、200円×2人×2泊＝800円です。乳幼児1人は課税対象かどうか材料に記載がないため、含めていません。自治体の課税対象・免除条件を確認してください。"},"audits":[{"by":"kansa","verdict":"send_back","reasons":["not_from_facts：材料に所在地の記載はないのに「宮崎市」と書いています。地名を削り、「自治体の課税対象・免除条件を確認してください」などの一般的な表現にしてください。"]},{"by":"kansa","verdict":"ok","reasons":[]}],"attempts":2,"flagged":false}', 0, 1, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
