INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-no_skill-minpaku-03', 'minpaku-03', 'b20261104T051207', 'no_skill', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":0,"basis":"予約が取り消しになったため宿泊は行われておらず、宿泊税は課税対象外です。預かった1,200円は市に納めず、ゲストに返す扱いとなります。キャンセル料の10,000円は宿泊の対価ではないため、宿泊税の計算には含めません。よって市に納める額は0円です。"},"audits":[{"by":"kansa","verdict":"ok","reasons":[]}],"attempts":1,"flagged":false}', 1, 0, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-no_skill-minpaku-04', 'minpaku-04', 'b20261104T051207', 'no_skill', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":155,"basis":"民泊新法の180日は、部屋数に関係なく宿泊させた日を1日と数え、重なった日は1回だけ数えます。A室は11/1〜11/4の4泊、B室は11/3〜11/5の3泊で、重なる11/3と11/4を1回ずつにすると、宿泊した日は11/1〜11/5の5日分です。今年度これまでの150日に5日を足して155日になります。"},"audits":[{"by":"kansa","verdict":"send_back","reasons":["wrong_number：民泊新法の180日は部屋数に関係なく「宿泊させた日」を1日として数え、重なった日は1回だけ数えます。夜は11/1〜11/5の5日分なので、合計は150+5=155日です。valueを155に直してください。","other：数え方を「夜数をそのまま足す」とした説明は制度上誤りで、オーナーに上限超過の判断を誤らせるおそれがあります。重なった日は1日として数えるという方式だけを示し、157日の案は削除してください。"]},{"by":"kansa","verdict":"ok","reasons":[]}],"attempts":2,"flagged":false}', 1, 0, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
INSERT INTO eval_runs (id, case_id, batch_id, variant, model, output_json, correct, missed, false_alarm, run_at) VALUES ('b20261104T051207-no_skill-minpaku-05', 'minpaku-05', 'b20261104T051207', 'no_skill', 'claude-sonnet-5-5 + claude-opus-5-5', '{"answer":{"value":8,"basis":"民泊新法（住宅宿泊事業法）では年間の宿泊日数の上限が180日です。180日から使用済みの172日を引くと、残りは8日です。"},"audits":[{"by":"kansa","verdict":"ok","reasons":[]}],"attempts":1,"flagged":false}', 1, 0, 0, '2026-11-04 05:15:02') ON CONFLICT (id) DO NOTHING;
